// Scheduler "Publish To X" v3 (media + NITKI, 06/07): kontrakt wyjscia 1:1 + media_ids/media_errors/thread_ids.
// Nitka: content dzielony po liniach ===TWEET===, kazdy kolejny post = reply do poprzedniego.
const rawText = ($json.content || '').toString();
const postId = $json.id;
if (!rawText.trim()) { return [{ json: { skipped: true, postId, error: 'empty content' } }]; }
const K0 = $('Get Keys').first().json;
const K = { ck: K0.ck, cs: K0.cs, at: K0.at, ats: K0.ats };
const TG = K0.tg || '';

// WSPOLNE HELPERY MEDIA v2 (21/07/2026, docs.x.com media-upload-chunked): Telegram getFile/download
// -> X v2 POST /2/media/upload. KONTRAKT: WSZYSTKIE parametry (command/media_type/total_bytes/
// media_category/media_id/segment_index) w multipart/form-data BODY - nie w query stringu
// (query dawal INIT 400 "query parameter [media_type] is not one of []"). STATUS = GET z query.
// OAuth1: przy multipart sygnatura obejmuje wylacznie oauth_* (body poza sygnatura).
// Fakty: docs/research/X_MEDIA_API_2026 (v1.1 DEAD, v2 chunked, OAuth1 dziala, Telegram 20MB getFile).
function _enc(s){return encodeURIComponent(s);}
function oauthAuth(method, url, K, extraParams){
  const crypto=require("crypto");
  const op={oauth_consumer_key:K.ck,oauth_nonce:crypto.randomBytes(16).toString("hex"),
    oauth_signature_method:"HMAC-SHA1",oauth_timestamp:Math.floor(Date.now()/1000).toString(),
    oauth_token:K.at,oauth_version:"1.0"};
  const all=Object.assign({},op,extraParams||{});
  const sorted=Object.keys(all).sort().map(function(k){return _enc(k)+"="+_enc(all[k]);}).join("&");
  const sigBase=method+"&"+_enc(url)+"&"+_enc(sorted);
  const sig=require("crypto").createHmac("sha1",_enc(K.cs)+"&"+_enc(K.ats)).update(sigBase).digest("base64");
  return "OAuth "+Object.keys(op).sort().map(function(k){return _enc(k)+'="'+_enc(op[k])+'"';}).join(", ")
    +', oauth_signature="'+_enc(sig)+'"';
}
function _req(opts, bodyBuf){
  const https=require("https");
  return new Promise(function(resolve,reject){
    const r=https.request(opts,function(res){
      const d=[];res.on("data",function(c){d.push(c);});
      res.on("end",function(){const buf=Buffer.concat(d);let j={};
        try{j=JSON.parse(buf.toString("utf8"));}catch(e){}
        resolve({status:res.statusCode,json:j,buf:buf});});});
    r.on("error",reject); if(bodyBuf){r.write(bodyBuf);} r.end();});
}
async function tgFetch(tg, fileId){
  const gf=await _req({hostname:"api.telegram.org",path:"/bot"+tg+"/getFile?file_id="+_enc(fileId),method:"GET"});
  const fp=gf.json&&gf.json.result&&gf.json.result.file_path; if(!fp){return null;}
  const dl=await _req({hostname:"api.telegram.org",path:"/file/bot"+tg+"/"+fp,method:"GET"});
  if(dl.status!==200||!dl.buf||!dl.buf.length){return null;}
  let mime="image/jpeg";
  if(fp.endsWith(".png")){mime="image/png";}
  else if(fp.endsWith(".webp")){mime="image/webp";}
  else if(fp.endsWith(".mp4")||fp.endsWith(".mov")){mime="video/mp4";}
  return {buf:dl.buf,mime:mime};
}
function _sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function _mid(j){return (j&&((j.data&&(j.data.id||j.data.media_id))||j.media_id_string))||null;}
function _mpb(fields, fileBuf){
  const bnd="agsb"+Date.now()+Math.floor(Math.random()*1e6);
  const parts=[];
  for(const k of Object.keys(fields)){
    parts.push(Buffer.from("--"+bnd+"\r\nContent-Disposition: form-data; name=\""+k+"\"\r\n\r\n"+fields[k]+"\r\n"));
  }
  if(fileBuf){
    parts.push(Buffer.from("--"+bnd+"\r\nContent-Disposition: form-data; name=\"media\"; filename=\"m\"\r\nContent-Type: application/octet-stream\r\n\r\n"));
    parts.push(fileBuf); parts.push(Buffer.from("\r\n"));
  }
  parts.push(Buffer.from("--"+bnd+"--\r\n"));
  return {buf:Buffer.concat(parts), ct:"multipart/form-data; boundary="+bnd};
}
async function xUpload(K, media){
  const isVideo=media.mime.indexOf("video")===0;
  // v3 (22/07): chunked przez pod-sciezki initialize/append/finalize (kontrakt docs.x.com;
  // /2/media/upload BEZ pod-sciezki to prosty upload i INIT tam dawal 400 "Missing media field").
  const ib=JSON.stringify({media_type:media.mime,total_bytes:media.buf.length,
                           media_category:isVideo?"tweet_video":"tweet_image"});
  const iu="https://api.x.com/2/media/upload/initialize";
  const ir=await _req({hostname:"api.x.com",path:"/2/media/upload/initialize",method:"POST",
    headers:{Authorization:oauthAuth("POST",iu,K,null),"Content-Type":"application/json",
             "Content-Length":Buffer.byteLength(ib)}},Buffer.from(ib));
  const mid=_mid(ir.json);
  if(!mid){return {error:"INIT "+ir.status+" "+JSON.stringify(ir.json).slice(0,180)};}
  // APPEND w kawalkach po 4MB (wideo do ~20MB z Telegrama = do 5 kawalkow)
  const CH=4*1024*1024;
  for(let seg=0; seg*CH<media.buf.length; seg++){
    const part=media.buf.slice(seg*CH,(seg+1)*CH);
    const ap=_mpb({segment_index:String(seg)},part);
    const au="https://api.x.com/2/media/upload/"+mid+"/append";
    const ar=await _req({hostname:"api.x.com",path:"/2/media/upload/"+mid+"/append",method:"POST",
      headers:{Authorization:oauthAuth("POST",au,K,null),"Content-Type":ap.ct,"Content-Length":ap.buf.length}},ap.buf);
    if(ar.status<200||ar.status>=300){return {error:"APPEND seg"+seg+" "+ar.status+" "+JSON.stringify(ar.json).slice(0,150)};}
  }
  const fu="https://api.x.com/2/media/upload/"+mid+"/finalize";
  const fr=await _req({hostname:"api.x.com",path:"/2/media/upload/"+mid+"/finalize",method:"POST",
    headers:{Authorization:oauthAuth("POST",fu,K,null),"Content-Length":0}});
  if(fr.status<200||fr.status>=300){return {error:"FINALIZE "+fr.status+" "+JSON.stringify(fr.json).slice(0,180)};}
  // wideo: przetwarzanie asynchroniczne - poll STATUS do succeeded (max ~100s)
  let pi=(fr.json&&(fr.json.processing_info||(fr.json.data&&fr.json.data.processing_info)))||null;
  let waited=0;
  while(pi&&pi.state&&pi.state!=="succeeded"){
    if(pi.state==="failed"){return {error:"processing failed"};}
    const wait=Math.min((pi.check_after_secs||3),10)*1000;
    if(waited>100000){return {error:"processing timeout"};}
    await _sleep(wait); waited+=wait;
    const sp={command:"STATUS",media_id:String(mid)};
    const sq=Object.keys(sp).map(function(k){return _enc(k)+"="+_enc(sp[k]);}).join("&");
    const sr=await _req({hostname:"api.x.com",path:"/2/media/upload?"+sq,method:"GET",
      headers:{Authorization:oauthAuth("GET","https://api.x.com/2/media/upload",K,sp)}});
    pi=(sr.json&&(sr.json.processing_info||(sr.json.data&&sr.json.data.processing_info)))||null;
    if(!pi){break;}
  }
  return {media_id:String(_mid(fr.json)||mid)};
}
async function collectMediaIds(K, tg, mediaField){
  let list=mediaField;
  if(typeof list==="string"){try{list=JSON.parse(list);}catch(e){list=[];}}
  if(!Array.isArray(list)){list=[];}
  const ids=[],errs=[];
  for(const m of list.slice(0,4)){
    if(!(m&&m.file_id)){continue;}
    if(!tg){errs.push("brak tg tokena");continue;}
    const dl=await tgFetch(tg,m.file_id);
    if(!dl){errs.push("tg download fail");continue;}
    const up=await xUpload(K,dl);
    if(up.media_id){ids.push(up.media_id);}else{errs.push(up.error||"upload fail");}
  }
  return {ids:ids,errs:errs};
}


async function postTweet(text, mediaIds, replyTo) {
  const payload = { text: text };
  if (mediaIds && mediaIds.length) { payload.media = { media_ids: mediaIds }; }
  if (replyTo) { payload.reply = { in_reply_to_tweet_id: replyTo }; }
  const body = JSON.stringify(payload);
  const auth = oauthAuth("POST", "https://api.twitter.com/2/tweets", K, null);
  return await _req({ hostname: "api.twitter.com", path: "/2/tweets", method: "POST",
    headers: { "Authorization": auth, "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) } },
    Buffer.from(body));
}

const mediaRes = await collectMediaIds(K, TG, $json.media);
const parts = rawText.split(/\n?\s*===TWEET===\s*\n?/).map(function(s){return s.trim();}).filter(Boolean);
const threadIds = [];
let firstStatus = 0;
for (let i = 0; i < parts.length; i++) {
  // media tylko na pierwszym poscie nitki
  const r = await postTweet(parts[i], i === 0 ? mediaRes.ids : [], threadIds.length ? threadIds[threadIds.length - 1] : null);
  if (i === 0) { firstStatus = r.status; }
  const tid = (r.json && r.json.data && r.json.data.id) || "";
  if (!tid) { break; }
  threadIds.push(tid);
}
const tweetId = threadIds[0] || "";
const tweetUrl = tweetId ? ("https://x.com/i/web/status/" + tweetId) : "";
return [{ json: { tweet_id: tweetId, tweet_url: tweetUrl, tweet_text: parts[0] || rawText, postId: postId,
  x_status: firstStatus, ok: (firstStatus === 200 || firstStatus === 201) && threadIds.length === parts.length,
  media_ids: mediaRes.ids, media_errors: mediaRes.errs, thread_ids: threadIds, thread_len: parts.length } }];

// Scheduler "Publish To LinkedIn" (22/07): kanon 'zatwierdzone publikuje sie ZAWSZE'
// wraca na LinkedIn PRZEZ SCHEDULER. Kod przeniesiony 1:1 z Subagent LinkedIn Publisher v2
// (registerUpload feedshare-image -> PUT -> ugcPosts). Kontrakt wyjscia jak Publish To X.
const K0=$('Get Keys').first().json;
const token=K0.li_token, author=K0.li_author, TG=K0.tg||'';
const text=($json.content||'').toString();
const postId=$json.id;
if(!text.trim()){ return [{json:{ok:false,postId:postId,error:'empty content'}}]; }
if(!token||!author){ return [{json:{ok:false,postId:postId,error:'missing linkedin_access_token/linkedin_author_urn in app_secrets'}}]; }
const https=require('https');
function req(opts, bodyBuf){
  return new Promise(function(resolve,reject){
    const r=https.request(opts,function(res){
      const d=[];res.on('data',function(c){d.push(c);});
      res.on('end',function(){const buf=Buffer.concat(d);let j={};
        try{j=JSON.parse(buf.toString('utf8'));}catch(e){}
        resolve({status:res.statusCode,json:j,buf:buf,hdr:res.headers});});});
    r.on('error',reject); if(bodyBuf){r.write(bodyBuf);} r.end();});
}
async function tgFetch(fileId){
  if(!TG){return null;}
  const gf=await req({hostname:'api.telegram.org',path:'/bot'+TG+'/getFile?file_id='+encodeURIComponent(fileId),method:'GET'});
  const fp=gf.json&&gf.json.result&&gf.json.result.file_path; if(!fp){return null;}
  const dl=await req({hostname:'api.telegram.org',path:'/file/bot'+TG+'/'+fp,method:'GET'});
  if(dl.status!==200||!dl.buf||!dl.buf.length){return null;}
  return dl.buf;
}
async function liUpload(buf, isVideo){
  const recipe=isVideo?'urn:li:digitalmediaRecipe:feedshare-video':'urn:li:digitalmediaRecipe:feedshare-image';
  const regBody=JSON.stringify({registerUploadRequest:{recipes:[recipe],
    owner:author,serviceRelationships:[{relationshipType:'OWNER',identifier:'urn:li:userGeneratedContent'}]}});
  const reg=await req({hostname:'api.linkedin.com',path:'/v2/assets?action=registerUpload',method:'POST',
    headers:{'Authorization':'Bearer '+token,'Content-Type':'application/json',
             'X-Restli-Protocol-Version':'2.0.0','Content-Length':Buffer.byteLength(regBody)}},Buffer.from(regBody));
  const v=reg.json&&reg.json.value; if(!v){return {error:'registerUpload '+reg.status};}
  const asset=v.asset;
  const mech=v.uploadMechanism&&v.uploadMechanism['com.linkedin.digitalmedia.uploading.MediaUploadHttpRequest'];
  const up=mech&&mech.uploadUrl; if(!(asset&&up)){return {error:'no uploadUrl'};}
  const mu=up.match(/^https:\/\/([^\/]+)(\/.*)$/); if(!mu){return {error:'bad uploadUrl'};}
  const put=await req({hostname:mu[1],path:mu[2],method:'PUT',
    headers:{'Authorization':'Bearer '+token,'Content-Type':'application/octet-stream','Content-Length':buf.length}},buf);
  if(put.status<200||put.status>=300){return {error:'PUT '+put.status};}
  return {asset:asset};
}
let mediaList=$json.media; if(typeof mediaList==='string'){try{mediaList=JSON.parse(mediaList);}catch(e){mediaList=[];}}
if(!Array.isArray(mediaList)){mediaList=[];}
const vids=mediaList.filter(function(m){return m&&m.file_id&&m.kind==='video';});
const pics=mediaList.filter(function(m){return m&&m.file_id&&m.kind!=='video';});
const useList=vids.length?[vids[0]]:pics.slice(0,4);
const isVideoPost=vids.length>0;
const assets=[],merrs=[];
for(const md of useList){
  const buf=await tgFetch(md.file_id); if(!buf){merrs.push('tg download fail');continue;}
  const upd=await liUpload(buf,isVideoPost); if(upd.asset){assets.push(upd.asset);}else{merrs.push(upd.error||'upload fail');}
}
const share={shareCommentary:{text:text},shareMediaCategory:assets.length?(isVideoPost?'VIDEO':'IMAGE'):'NONE'};
if(assets.length){share.media=assets.map(function(a){return {status:'READY',media:a};});}
const payload=JSON.stringify({author:author,lifecycleState:'PUBLISHED',
  specificContent:{'com.linkedin.ugc.ShareContent':share},
  visibility:{'com.linkedin.ugc.MemberNetworkVisibility':'PUBLIC'}});
const result=await req({hostname:'api.linkedin.com',path:'/v2/ugcPosts',method:'POST',
  headers:{'Authorization':'Bearer '+token,'Content-Type':'application/json',
           'X-Restli-Protocol-Version':'2.0.0','Content-Length':Buffer.byteLength(payload)}},Buffer.from(payload));
const urn=(result.json&&result.json.id)||(result.hdr&&result.hdr['x-restli-id'])||'';
const url=urn?('https://www.linkedin.com/feed/update/'+urn):'';
return [{json:{ok:(result.status===201||result.status===200),postId:postId,
  tweet_id:String(urn),tweet_url:url,tweet_text:text.slice(0,120),x_status:result.status,
  li_err:(result.json&&result.json.message)||null,media_assets:assets,media_errors:merrs}}];
